-- ============================================
-- LUMA — Thème 16 : 3e scénario COURT x4 — Une rencontre avec la faune sauvage sur la route
-- ============================================


update scenarios set content = '{"characters": {"local": "un local rencontré à une station essence"}, "start_node": "n1", "nodes": {"n1": {"speaker": "local", "text": "Careful on this stretch — kangaroos cross the road a lot at dusk.", "text_fr": "Attention sur ce tronçon — les kangourous traversent souvent la route au crépuscule.", "choices": [{"text": "Thanks for the warning, should I avoid driving at that time?", "text_fr": "Merci pour l''avertissement, je devrais éviter de conduire à ce moment-là ?", "next": "n2"}, {"text": "I actually saw one already, it was amazing!", "text_fr": "J''en ai déjà vu un en fait, c''était incroyable !", "next": "n2b"}]}, "n2": {"speaker": "local", "text": "Best to avoid dawn and dusk if you can, or just drive slow and stay alert.", "text_fr": "Mieux vaut éviter l''aube et le crépuscule si possible, ou rouler lentement et rester attentif.", "choices": [{"text": "Good advice, I''ll be extra careful.", "text_fr": "Bon conseil, je vais faire très attention.", "next": "n3"}]}, "n2b": {"speaker": "local", "text": "Ha, they''re everywhere out here! Just don''t hit one, they can total a car.", "text_fr": "Ha, il y en a partout par ici ! Évitez juste d''en percuter un, ça peut détruire une voiture.", "choices": [{"text": "Noted, I''ll keep my eyes peeled.", "text_fr": "Compris, je vais garder l''œil ouvert.", "next": "n3"}]}, "n3": {"speaker": "local", "text": "Also watch for wombats at night, they''re stubborn and won''t move for cars.", "text_fr": "Faites aussi attention aux wombats la nuit, ils sont têtus et bougeront pas pour les voitures.", "choices": [{"text": "Good to know, I''ll slow down significantly after dark then.", "text_fr": "Bon à savoir, je vais ralentir significativement après la tombée de la nuit alors.", "next": "n4"}, {"text": "Are there other animals I should watch for on this route?", "text_fr": "Il y a d''autres animaux dont je devrais me méfier sur cette route ?", "next": "n4"}]}, "n4": {"speaker": "local", "text": "Emus sometimes too, though they''re easier to spot being so tall.", "text_fr": "Des émeus parfois aussi, même s''ils sont plus faciles à repérer étant si grands.", "choices": [{"text": "Thanks for all the tips, this is really helpful for the drive ahead.", "text_fr": "Merci pour tous les conseils, c''est vraiment utile pour la route à venir.", "next": "n5"}]}, "n5": {"speaker": "local", "text": "No worries at all, better prepared than sorry out here.", "text_fr": "Aucun souci, mieux vaut être préparé que désolé par ici.", "choices": [{"text": "Absolutely, I''ll drive extra carefully. Thanks again!", "text_fr": "Absolument, je vais conduire super prudemment. Merci encore !", "next": "end_careful"}]}, "end_careful": {"speaker": "local", "text": "Safe travels out there, mate.", "text_fr": "Bonne route.", "end": true, "ending_label": "Conseils de sécurité routière bien reçus 🦘🚗"}}}'::jsonb, is_playable = true
where title = 'Une rencontre avec la faune sauvage sur la route'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
